(function () {
  'use strict';
  var Core = window.FocusCore, KEY = 'focus-sprint-planner-v1';
  var els = {
    form: document.getElementById('task-form'), title: document.getElementById('task-title'), minutes: document.getElementById('task-minutes'),
    editing: document.getElementById('editing-id'), cancel: document.getElementById('cancel-edit'), save: document.getElementById('save-task'),
    list: document.getElementById('task-list'), empty: document.getElementById('empty'), feedback: document.getElementById('feedback'), summary: document.getElementById('summary'),
    sprint: document.getElementById('sprint-length'), clear: document.getElementById('clear-selection'), count: document.getElementById('task-count')
  };
  var loaded = Core.loadState(window.localStorage, KEY), state = loaded.state;
  if (loaded.warning) show(loaded.warning, 'notice');
  els.sprint.value = String(state.sprintMinutes);

  function show(message, type) { els.feedback.textContent = message; els.feedback.className = 'feedback ' + (type || ''); }
  function persist() { var result = Core.saveState(window.localStorage, KEY, state); if (!result.ok) show(result.warning, 'notice'); }
  function render() {
    state = Core.sanitizeState(state);
    var summary = Core.summarizeSprint(state);
    els.summary.textContent = 'Selected: ' + summary.total + ' min · Remaining: ' + summary.remaining + ' min' + (summary.over ? ' · Over budget by ' + (summary.total - summary.sprintMinutes) + ' min' : '');
    els.summary.className = 'summary' + (summary.over ? ' over' : '');
    els.count.textContent = state.tasks.length + '/100';
    els.list.textContent = '';
    els.empty.hidden = state.tasks.length > 0;
    state.tasks.forEach(function (task) {
      var item = document.createElement('li'); item.className = 'task';
      var check = document.createElement('input'); check.type = 'checkbox'; check.checked = state.selectedIds.indexOf(task.id) >= 0; check.setAttribute('aria-label', 'Select ' + task.title);
      check.addEventListener('change', function () { toggle(task.id, check.checked); });
      var name = document.createElement('span'); name.className = 'task-title'; name.textContent = task.title;
      var time = document.createElement('span'); time.className = 'task-minutes'; time.textContent = task.minutes + ' min';
      var actions = document.createElement('span'); actions.className = 'task-actions';
      var edit = document.createElement('button'); edit.type = 'button'; edit.className = 'quiet'; edit.textContent = 'Edit'; edit.addEventListener('click', function () { beginEdit(task); });
      var remove = document.createElement('button'); remove.type = 'button'; remove.className = 'quiet'; remove.textContent = 'Remove'; remove.addEventListener('click', function () { removeTask(task.id); });
      actions.append(edit, remove); item.append(check, name, time, actions); els.list.append(item);
    });
  }
  function toggle(id, checked) { state.selectedIds = state.selectedIds.filter(function (value) { return value !== id; }); if (checked) state.selectedIds.push(id); persist(); render(); }
  function resetForm() { els.form.reset(); els.editing.value = ''; els.cancel.hidden = true; els.save.textContent = 'Add task'; }
  function beginEdit(task) { els.title.value = task.title; els.minutes.value = task.minutes; els.editing.value = task.id; els.cancel.hidden = false; els.save.textContent = 'Save task'; els.title.focus(); }
  function removeTask(id) { state.tasks = state.tasks.filter(function (task) { return task.id !== id; }); state.selectedIds = state.selectedIds.filter(function (value) { return value !== id; }); persist(); render(); show('Task removed.'); }
  els.form.addEventListener('submit', function (event) {
    event.preventDefault(); var title = els.title.value.trim(), minutes = Number(els.minutes.value);
    if (!title || title.length > 100 || !Number.isInteger(minutes) || minutes < 1 || minutes > 480) { show('Enter a title up to 100 characters and a whole number of minutes from 1 to 480.', 'error'); return; }
    var id = els.editing.value;
    if (id) { var task = state.tasks.find(function (item) { return item.id === id; }); if (task) { task.title = title; task.minutes = minutes; } }
    else { if (state.tasks.length >= 100) { show('You can have up to 100 tasks.', 'error'); return; } state.tasks.push({ id: Date.now().toString(36) + Math.random().toString(36).slice(2), title: title, minutes: minutes }); }
    persist(); resetForm(); render(); show(id ? 'Task updated.' : 'Task added.');
  });
  els.cancel.addEventListener('click', resetForm);
  els.sprint.addEventListener('change', function () { state.sprintMinutes = Number(els.sprint.value); persist(); render(); });
  els.clear.addEventListener('click', function () { state.selectedIds = []; persist(); render(); show('Selection cleared.'); });
  render();
}());

app.test.js:
const test = require('node:test');
const assert = require('node:assert/strict');
const Core = require('./core.js');

const valid = { tasks: [{ id: 'a', title: '  Write outline  ', minutes: 20 }], selectedIds: ['a'], sprintMinutes: 25 };

test('sanitizes invalid, duplicate, unknown, and oversized state values', () => {
  const state = Core.sanitizeState({
    tasks: [valid.tasks[0], { id: 'a', title: 'duplicate', minutes: 2 }, { id: 'b', title: '', minutes: 3 }, { id: 'c', title: 'bad time', minutes: 481 }, { id: 'd', title: 'x'.repeat(120), minutes: 4 }],
    selectedIds: ['a', 'a', 'missing'], sprintMinutes: 0
  });
  assert.deepEqual(state.tasks, [{ id: 'a', title: 'Write outline', minutes: 20 }, { id: 'd', title: 'x'.repeat(100), minutes: 4 }]);
  assert.deepEqual(state.selectedIds, ['a']);
  assert.equal(state.sprintMinutes, 25);
});

test('summarizes selected work and over-budget status', () => {
  assert.deepEqual(Core.summarizeSprint({ ...valid, tasks: [{ id: 'a', title: 'one', minutes: 30 }], sprintMinutes: 25 }), { total: 30, sprintMinutes: 25, remaining: 0, over: true });
});

test('reports corrupt and inaccessible storage while returning safe state', () => {
  const corrupt = Core.loadState({ getItem: () => '{' }, 'key');
  assert.equal(corrupt.state.tasks.length, 0);
  assert.match(corrupt.warning, /invalid/);
  const blocked = Core.loadState({ getItem: () => { throw new Error('blocked'); } }, 'key');
  assert.match(blocked.warning, /could not be read/);
});

test('reports quota failure and sanitizes what it writes', () => {
  let written;
  const storage = { setItem: (key, value) => { written = JSON.parse(value); } };
  assert.equal(Core.saveState(storage, 'key', valid).ok, true);
  assert.equal(written.tasks[0].title, 'Write outline');
  const quota = Core.saveState({ setItem: () => { throw new Error('quota'); } }, 'key', valid);
  assert.equal(quota.ok, false);
  assert.match(quota.warning, /full or blocked/);
});

test('validates task shape and minute boundaries', () => {
  assert.equal(Core.validTask({ id: 'x', title: 'Task', minutes: 1 }), true);
  assert.equal(Core.validTask({ id: 'x', title: 'Task', minutes: 480 }), true);
  assert.equal(Core.validTask({ id: 'x', title: 'Task', minutes: 0 }), false);
  assert.equal(Core.validTask({ id: 'x', title: 'Task', minutes: 481 }), false);
});
